function lineVisual(data,names){const w=760,h=215,pad=30,vals=data.flatMap(x=>x.values).filter(x=>x!==null),min=Math.min(0,...vals),max=Math.max(1,...vals),y=v=>h-pad-(v-min)/(max-min)*(h-pad*2),x=i=>pad+i/Math.max(1,data.length-1)*(w-pad*2);let paths=names.map((name,s)=>{let path='',connected=false;data.forEach((d,i)=>{const v=d.values[s];if(v===null){connected=false;return}path+=(connected?' L':' M')+x(i).toFixed(2)+' '+y(v).toFixed(2);connected=true});return `<path d="${path}" fill="none" stroke="${chartColors[s]}" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/>${data.map((d,i)=>d.values[s]===null?'':`<circle cx="${x(i)}" cy="${y(d.values[s])}" r="3.4" fill="${chartColors[s]}"><title>${esc(name)} · ${esc(d.label)}: ${d.values[s].toLocaleString('en-BD')}</title></circle>`).join('')}`}).join('');return `<div class="visual-legend">${names.map((n,i)=>`<span><i style="background:${chartColors[i]}"></i>${esc(n)}</span>`).join('')}</div><div class="line-chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(names.join(' and '))} trend">${[0,.25,.5,.75,1].map(t=>`<line x1="${pad}" y1="${pad+t*(h-pad*2)}" x2="${w-pad}" y2="${pad+t*(h-pad*2)}" stroke="#e8eee5" stroke-dasharray="3 5"/>`).join('')}<line x1="${pad}" y1="${y(0)}" x2="${w-pad}" y2="${y(0)}" stroke="#d5decf"/>${paths}${data.filter((d,i)=>i===0||i===data.length-1||i%Math.ceil(data.length/6)===0).map(d=>{const i=data.indexOf(d);return `<text x="${x(i)}" y="${h-4}" text-anchor="middle" fill="#899282" font-size="10">${esc(d.label)}</text>`}).join('')}</svg></div>`}
function horizontalVisual(rows,unit='count',actions=false){const max=Math.max(1,...rows.map(r=>Math.abs(r.value||0)));return `<div class="horizontal-visual">${rows.map((r,i)=>`<${actions?'button':'div'} class="visual-bar-row" ${actions?`onclick="${r.action}"`:''}><span>${esc(r.label)}</span><div><i style="width:${Math.max(0,Math.abs(r.value||0)/max*100)}%;background:${r.value<0?'#d89180':chartColors[i%chartColors.length]}"></i></div><strong>${r.value==null?'Cost missing':unit==='money'?money(r.value):r.value}</strong></${actions?'button':'div'}>`).join('')||empty('No data in this period.')}</div>`}
